const { z } = require('zod');

const emailSchema = z.string().trim().toLowerCase().email('Enter a valid email').max(254);
const anyPassword = z.string().min(1, 'Password is required').max(200);

module.exports = {
  changeEmail: z.object({ password: anyPassword, newEmail: emailSchema }),
  confirmPassword: z.object({ password: anyPassword }),
  sessionParams: z.object({ familyId: z.string().uuid() })
};
